import{postJSON as s}from"./api.js";import{showNotice as e}from"./format.js";import{applyTranslations as m,t as l}from"./i18n.js";import{initPreferences as d}from"./prefs.js";d();m();const o=document.getElementById("login-form"),r=document.getElementById("login-status"),n=document.getElementById("login-submit");o?.addEventListener("submit",async i=>{i.preventDefault(),e(r,""),n.disabled=!0;const t=new FormData(o);try{await s("/api/login",{username:String(t.get("username")||""),password:String(t.get("password")||"")},{allowUnauthorized:!0}),window.location.href="/"}catch(a){e(r,l("notice.signInFailed",{error:a.message}),"error")}finally{n.disabled=!1}});
